package com.bank.benmatch.service;

import java.util.logging.Logger;

// Levenshtein edit distance via a 2D prefix table.
public class BeneficiaryMatchService {
    private static final Logger log = Logger.getLogger(BeneficiaryMatchService.class.getName());

    public int editDistance(String typed, String registered) {
        int m = typed.length(), n = registered.length();
        int[][] dp = new int[m + 1][n + 1];         // dp[i][j] = edits for prefixes
        for (int i = 0; i <= m; i++) dp[i][0] = i;  // delete all i chars
        for (int j = 0; j <= n; j++) dp[0][j] = j;  // insert all j chars
        for (int i = 1; i <= m; i++) {
            for (int j = 1; j <= n; j++) {
                if (typed.charAt(i - 1) == registered.charAt(j - 1)) {
                    dp[i][j] = dp[i - 1][j - 1];    // match, no edit
                } else {
                    int substitute = dp[i - 1][j - 1];
                    int delete = dp[i - 1][j];
                    int insert = dp[i][j - 1];
                    dp[i][j] = 1 + Math.min(substitute, Math.min(delete, insert));
                }
            }
        }
        final int r = dp[m][n];
        log.info(() -> "Edit distance " + typed + " to " + registered + " = " + r);
        return r;
    }
}
